package main

import (
    "fmt"
    "path/filepath"
)

func main() {
    paths := []string{"reports/archive.tar.gz", "reports/2026/", ".env", ""}
    for _, value := range paths {
        fmt.Printf("path=%q directory=%q name=%q extension=%q\n",
            value, filepath.Dir(value), filepath.Base(value), filepath.Ext(value))
    }
}
